changeSet.sql:
create or alter procedure api.ValidateLookupFields @lookupPassedByValue bit as begin --create table #Items (ItemNumber int, IsValid bit, ObjectID int, AssetID bigint); --create table #Fields (ItemNumber int, FieldName nvarchar(250), FieldTypeID int, FieldValue nvarchar(max), LookupValue nvarchar(max));
declare @listFieldTypes table (FieldTypeID int, AllowMultipleValues bit);
insert into @listFieldTypes select t.FieldTypeID, s.AllowMultipleValues from #Fields t inner join FieldType s on s.ID = t.FieldTypeID and s.[Type] = 'Lookup' group by t.FieldTypeID, s.AllowMultipleValues;
-- Resolve lookup field values. if exists (select 1 from @listFieldTypes) begin if @lookupPassedByValue = 1 begin if exists(select 1 from @listFieldTypes where AllowMultipleValues = 0) begin update T set T.LookupValue = T.[FieldValue] from #Fields T inner join @listFieldTypes ST on ST.FieldTypeID = T.FieldTypeID and ST.AllowMultipleValues = 0 inner join FieldLookupValue flv on flv.FieldTypeID = T.FieldTypeID and flv.Value = try_parse(T.[FieldValue] as int); end
if exists(select 1 from @listFieldTypes where AllowMultipleValues = 1) begin drop table if exists #tempFieldValueMulti;
select T.ItemNumber,T.FieldTypeID,try_parse(Val.[Value] as int) FieldValue,0 IsExists into #tempFieldValueMulti from #Fields T inner join @listFieldTypes ST on ST.FieldTypeID = T.FieldTypeID and ST.AllowMultipleValues = 1 cross apply (select Value from string_split(T.[FieldValue], ','))Val(Value);
create clustered index cx_idx on #tempFieldValueMulti(ItemNumber,FieldTypeID);
Update t set t.IsExists = 1 from #tempFieldValueMulti T inner join FieldLookupValue flv on flv.FieldTypeID = T.FieldTypeID and flv.Value = T.FieldValue;
delete t from #tempFieldValueMulti T where exists (select 1 from #tempFieldValueMulti T1 where T1.ItemNumber = t.ItemNumber and T1.FieldTypeID = t.FieldTypeID and coalesce(T1.IsExists,0) != 1)
update T set T.LookupValue = T.[FieldValue] from #Fields T inner join #tempFieldValueMulti T1 on T1.ItemNumber = t.ItemNumber and T1.FieldTypeID = t.FieldTypeID and coalesce(T1.IsExists,0) = 1 end end else begin declare @uniqueListValues table (ID int identity(1,1), FieldTypeID int, AllowMultipleValues bit, FieldValue nvarchar(max), LookupValue nvarchar(max))
if exists(select 1 from @listFieldTypes where AllowMultipleValues = 1) begin insert into @uniqueListValues select t.FieldTypeID, s.AllowMultipleValues, tmv.[Value] FieldValue, null from #Fields t inner join @listFieldTypes s on s.FieldTypeID = t.FieldTypeID and s.AllowMultipleValues = 1 cross apply string_split(t.FieldValue, ',') tmv group by t.FieldTypeID, s.AllowMultipleValues, tmv.[Value]; end
if exists(select 1 from @listFieldTypes where AllowMultipleValues = 0) begin insert into @uniqueListValues select t.FieldTypeID, s.AllowMultipleValues, t.FieldValue, null from #Fields t inner join @listFieldTypes s on s.FieldTypeID = t.FieldTypeID and s.AllowMultipleValues = 0 group by t.FieldTypeID, s.AllowMultipleValues, t.FieldValue; end
update t set t.LookupValue = s.[Value] from @uniqueListValues t inner join FieldLookupValue s on s.FieldTypeID = t.FieldTypeID and trim(s.[Text]) = trim(t.FieldValue);
update t set t.LookupValue = s.LookupValue from #Fields t inner join @uniqueListValues s on s.FieldTypeID = t.FieldTypeID and s.FieldValue = t.FieldValue and s.AllowMultipleValues = 0;
drop table if exists #tempdatamulti;
select t.ItemNumber,t.FieldTypeID,tmv.ordinal,tmv.[Value], s.LookupValue into #tempdatamulti from #Fields t inner join @listFieldTypes ft on ft.FieldTypeID = t.FieldTypeID and ft.AllowMultipleValues = 1 cross apply (select * from string_split(t.FieldValue, ',', 1) s) tmv left join @uniqueListValues s on s.FieldTypeID = t.FieldTypeID and tmv.[Value] = s.FieldValue;
create clustered index cx_tempdatamulti on #tempdatamulti(ItemNumber,FieldTypeID);
delete t from #tempdatamulti t where exists (select 1 from #tempdatamulti t1 where t1.ItemNumber = t.ItemNumber and t1.FieldTypeID = t.FieldTypeID and t1.LookupValue is null);
update t set t.LookupValue = S.LookupValue from #Fields t inner join @listFieldTypes ft on ft.FieldTypeID = t.FieldTypeID and ft.AllowMultipleValues = 1 cross apply (select string_agg(tm.LookupValue, ',') within group(order by tm.ordinal) LookupValue from #tempdatamulti tm where tm.ItemNumber = t.ItemNumber and tm.FieldTypeID = t.FieldTypeID ) S end end end
